var CARD_SHADOWS=['none','0 1px 2px rgba(0,0,0,.06)','0 2px 8px rgba(0,0,0,.08)','0 4px 14px rgba(0,0,0,.10)','0 8px 24px rgba(0,0,0,.12)','0 16px 40px rgba(0,0,0,.16)'];
function cardCss(opts){
  opts=opts||{};
  var radius=opts.radius!=null?opts.radius:14;
  var pad=opts.padding!=null?opts.padding:20;
  var bg=opts.bg||'#ffffff';
  var border=opts.border!=null?opts.border:0.06;
  var w=opts.width!=null?opts.width:320;
  var s=Math.round(Number(opts.shadow!=null?opts.shadow:2));
  if(!(s>=0)) s=0; if(s>5) s=5;
  var L=[];
  L.push('.card {');
  L.push('  width: '+w+'px;');
  L.push('  background: '+bg+';');
  L.push('  border-radius: '+radius+'px;');
  L.push('  padding: '+pad+'px;');
  L.push('  box-shadow: '+CARD_SHADOWS[s]+';');
  L.push('  border: 1px solid rgba(0,0,0,'+border+');');
  L.push('}');
  return L.join('\n');
}

var EXPORTS={cardCss:cardCss,CARD_SHADOWS:CARD_SHADOWS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CardForgePure = EXPORTS; }
